-- qr_084: each focus word's "meaning here" cut to the point — a few words under its bold arc.
-- The source lines behind each (here_src_json, qr_082) are unchanged.

UPDATE qr_sarf_word SET here_en = 'the Book sent down from God, part by part' WHERE surah = 40 AND ayah = 2 AND word_index = 1;
